def predict(A):
    n=len(A);m=len(A[0]); out=[row[:] for row in A]
    seen=set(); cnts={}
    def dfs(v,st):
        stack=list(st); st.clear()
        while stack:
            r,c=stack.pop()
            if (r,c) in seen: continue
            seen.add((r,c))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<n and 0<=nc<m and A[nr][nc]==v:
                    stack.append((nr,nc))
    for r in range(n):
        for c in range(m):
            if A[r][c] != 0 and (r,c) not in seen:
                comp=[(r,c)]; seen.add((r,c)); cc=0
                while comp:
                    x,y=comp.pop(); cc+=1
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dr,y+dc
                        if 0<=nx<n and 0<=ny<m and A[nx][ny]!=0 and (nx,ny) not in seen:
                            seen.add((nx,ny)); comp.append((nx,ny))
                cnts.setdefault(cc,[]).append((r,c))
    for sz,cells in cnts.items():
        # hypothesis: size >= 2 -> color 8, else keep
        new_color = 8 if sz >= 2 else None
        for r,c in cells:
            if new_color is not None and out[r][c] != 8:
                out[r][c]=new_color
    return out

